scripts.姚公子对话.txt:
// 与姚公子的同伴对话

	If ($Event == 307) @Event307;
	Return;
	
@Event307:
	Say("姚公子：这里就是地牢了。", 71);
	Return;

scripts.张琳心对话.txt:
// 与张琳心的同伴对话

	If ($Event == 307) @Event307;
		
	Return;	
	
@Event307:
	Say("张琳心：这大牢里常年不见阳光，可想而知里面的囚犯过的是什么日子……", 27);
	Return;

traps.trap01.txt:
//切换到map053大牢看守的木屋

	If ($Event == 307) @Event307; 
	
	FadeOut();
	SaveNpc();
	SaveObj();
	LoadMap("map053_长安城大牢木屋.map");
	LoadNpc("map053.npc");
	LoadObj("map053.obj");
	SetPlayerPos(3, 15);
	SetPlayerDir(5);
	FadeIn();
	Return;
	
@Event307:
	Say("独孤剑：先救人要紧！", 1);
	Return;

traps.trap02.txt:
// 在大牢里救出李三和杨湖；回到酒店辞别张如梦，前往石塘镇

	If ($Event == 307) @Event307;
	Return;	
	
@Event307:

//在大牢里救出李三和杨湖

	SetNpcKind("姚公子", 1);
	SetNpcKind("张琳心", 1);
	NpcGoto("姚公子", 11, 22);
	SetNpcDir("姚公子", 5);
	Say("冯麻子：姚公子，您来啦？是不是又有什么人在外头呆得腻味了……", 0);
	Say("姚公子：少、少废话！去，把犯人放了！", 71);
	Say("冯麻子：这——如果知府大人追究下来，小的可担待不起呀……", 0);
	Say("姚公子：怎么？！我说的话都不听吗？我爹那边我自会交代，快、快放人！", 71);
	Say("牢房看守：是、是、是……", 0);
	Sleep(500);
	NpcGoto("冯麻子", 11, 18);
	SetNpcDir("冯麻子", 7);
	Sleep(500);
	NpcGotoEx("姚公子", 12, 17);
	NpcGotoEx("独孤剑", 11, 21);
	NpcGotoEx("独孤剑", 13, 17);
	NpcGotoEx("张琳心", 11, 21);
	NpcGoto("张琳心", 14, 18);
	Sleep(400);
	SetNpcDir("姚公子", 7);
	SetNpcDir("独孤剑", 4);
	SetNpcDir("张琳心", 4);
	
	Sleep(500);
	Say("李三：你们是谁？", 70);
	Say("独孤剑：在下衡山独孤剑，这位姑娘是张琳心，我们得知你被囚大牢，特来救你。", 1);
	Say("李三：多谢二位搭救，俺李三不知如何报答！", 70);
	Say("独孤剑：不必客气。其实，我们正有一事需要李兄帮忙。", 2);
	Say("李三：这位大哥，你们救俺离开这个不见天日的鬼地方，只要俺能做到的，赴汤蹈火，李三皱一皱眉头就不是好汉。", 70);
	Say("独孤剑：这里不是说话之地。请你先回石塘镇，我们办完一些事情后自会到石塘镇找你。", 1);
	Say("李三：也好。和我关在一起的还有一位叫杨湖的好汉，是位江湖中的朋友，二位能否一并将他放了？", 70);
	Say("独孤剑：好的，我们稍后去找你。", 2);
	Say("李三：他奶奶的，这狗贼将俺关在这里半日，可把俺憋坏了！", 70);
	NpcGoto("李三", 14, 19);
	NpcGoto("李三", 12, 20);
	NpcGoto("李三", 8, 22);
	DelNpc("李三");
	SaveNpc();
	
	SetPlayerDir(2);
	SetNpcDir("张琳心", 2);
	SetNpcDir("姚公子", 6);
	Say("独孤剑：把那个犯人也给放了。", 9);
	Say("姚公子：这……那个犯人非同一般，实在不能放。如果放了，我、我怕我爹不会饶我……", 71);
	Say("独孤剑：哼！你怕你爹不肯饶你，那你不怕我们不放过你吗？", 5); 
	Say("姚公子：大侠饶命！大侠饶命！大侠想、想放谁就放谁……", 71);
	Sleep(500);
	
	NpcGoto("杨湖", 14, 16);
	SetNpcDir("杨湖", 1);
	SetPlayerDir(5);
	SetNpcDir("张琳心", 4);
	Say("犯人：在下杨湖，多谢两位义士搭救。", 100);
	Say("独孤剑：不必客气。看杨兄也是江湖中人，不知如何沦落此处？", 1);
	Say("杨湖：说来话长，既然二位也是大宋的武林人士，我就不对你们隐瞒身份了。我是洞庭天王帮的右使，来长安调查一件事情，结果被内奸出卖，行藏暴露，被姚知节和金人联手抓住，多亏二位搭救。", 100);
	Say("杨湖：在下还有要事在身，这是本帮的信物天王令，二位以后若是有用得着本帮弟兄的地方，出示此令即可，本帮弟兄见令如见帮主本人，二位如有吩咐，本帮弟兄誓将赴汤蹈火，在所不辞。", 100);
	Say("独孤剑：多谢杨义士。", 2);
	Say("杨湖：后会有期。在下在洞庭湖恭候二位大驾。", 100);
	AddGoods("Goods406_天王令.ini");
	Sleep(500);
	NpcGoto("杨湖", 14, 19);
	NpcGoto("杨湖", 12, 20);
	NpcGoto("杨湖", 8, 22);
	DelNpc("杨湖");
	SaveNpc();
	
	SetPlayerDir(2);
	SetNpcDir("张琳心", 2);
	SetNpcDir("姚公子", 6);
	Say("独孤剑：这大牢里关的犯人十有八九是被你们欺压的老百姓，把所有的人全都给我放了。", 9);
	Say("姚公子：是，是，是……", 71);
	Sleep(500);
	SetMapTrap(2, "");	
	Assign($Event,309);
	Memo("独孤剑带着姚公子来到大牢顺利地救了李三，还同时解救了洞庭天王帮右使杨湖，杨湖送给独孤剑一块天王令。");
	
// 回到酒店	
	
	FadeOut();
	StopMusic();
	PlayMusic("春潮.mp3");
	SaveNpc();
	SaveObj();
	SetNpcKind("姚公子", 3);
	SetNpcKind("张琳心", 3);
	LoadMap("map050_1_长安酒店二楼.map");
	LoadNpc("map050_1.npc");
	LoadObj("map050_1.obj");
	SetPlayerPos(15, 27);
	SetPlayerDir(7);
	AddNpc("npc002_张如梦.ini", 16, 28, 3);
	SetNpcKind("姚公子", 1);
	SetNpcKind("张琳心", 1);
	SetNpcPos("姚公子", 14, 30);
	SetNpcDir("姚公子", 5);
	SetNpcPos("张琳心", 15, 28);
	SetNpcDir("张琳心", 6);
	FadeIn();
		
	Say("张如梦：哈哈哈，痛快痛快，那姚知节如果知道你们把所有的犯人都给放了，准会气歪了胡子……哈哈哈！", 12);
	Say("独孤剑：张兄，我们事情已经办完。你看这狗贼如何处置。", 1);
	Say("姚公子：饶命啊……", 71);
	Say("张如梦：你们把他交给我吧，我自有办法收拾他。", 12);
	Say("姚公子：……", 71);
	StopMusic();
	PlayMusic("前途.mp3");
	Say("张琳心：哥……爹，爹他，已经……", 26);
	Say("张如梦：爹，爹他怎么了……", 16);
	FadeOut();
	Say("张琳心将父亲去世的消息告诉了张如梦，并讲述了父亲忍辱负重多年为的是抗金大业。张如梦听后如五雷轰顶，当他终于了解自己的父亲时，却再也见不到他老人家了。", 0);
	Sleep(500);
	FadeIn();
	Say("张如梦：爹……孩儿真是太糊涂了！孩儿，对不起您老人家……", 17);
	Say("张如梦：我现在就回临安，回去给爹报仇！",17);
	Say("张琳心：不行！太危险了，你不能回去！",25);
	Say("独孤剑：不错，张兄！这样轻身犯险太不值得了。世伯不惜一死为的是保护“山河社稷图”，我们应当首先找回地图，了却世伯的遗愿；然后再去杀死南宫灭，为世伯报仇。",1);
	Say("张琳心：哥哥，这世上，琳心只有你一个亲人了……", 28);
	Say("张如梦：妹妹！……",17);
	Say("张如梦：我想回临安给爹的坟上上柱香……",17);
	Say("张琳心：哥哥，我和独孤大哥有很重要的事要上华山一趟，等事情办完后，我就回临安找你。", 21);
	Say("张如梦：好，你和独孤兄在一起，哥哥很放心，我不是一个好兄长……", 19);
	Say("张琳心：不！哥哥，你一直都是我的好哥哥！", 26);
	Say("张如梦：独孤兄，琳儿今后就拜托你了。", 11);
	Say("张如梦：今后危机重重，你们千万要小心！", 11);
	Say("独孤剑：张兄也要珍重。", 2);
	Say("张琳心：哥哥，你要好好保重，少喝些酒，千万别意气用事，以身犯险……", 24);
	Say("张如梦：嗯，我知道了……", 11);

	Assign($Event, 310);
	Memo("回到酒馆，张如梦决定回临安追查“山河社稷图”的下落。独孤剑和张琳心则准备二上华山。");
	
//	辞别张如梦，前往石塘镇	
	
	FadeOut();
	SetNpcKind("张琳心", 3);
	DelNpc("姚公子");
	DelNpc("张如梦");
	SaveNpc();
	SaveObj();
	LoadMap("map047_长安城东.map");
	LoadNpc("map047.npc");
	LoadObj("map047.obj");
	SetPlayerPos(7, 22);
	SetPlayerDir(1);
	SetNpcKind("张琳心", 1);
	SetNpcPos("张琳心", 6, 23);
	SetNpcDir("张琳心", 5);
	Say("辞别了张如梦以后，独孤剑和张琳心急匆匆地赶往石塘镇。", 0);
	FadeIn();
	Say("独孤剑：我们去石塘镇找李三吧。", 1);
	Say("张琳心：不知华山上的比武进行得怎样了？", 21);
	Say("独孤剑：是啊，真叫人担心，我总觉得比武的事情有点不对劲……", 1);
	SetNpcKind("张琳心", 3);
	Return;
